<?php
declare(strict_types=1); namespace Tests\Feature\Classrooms; use App\Models\User; use App\Services\Access\RoleService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class PermissionDependencyTest extends TestCase {use RefreshDatabase; public function test_classroom_operational_permission_requires_view_but_view_own_does_not():void{$this->seed(\Database\Seeders\AccessControlSeeder::class);$actor=User::first();$service=app(RoleService::class);$role=$service->create($actor,['display_name'=>'Uji','permissions'=>['classrooms.create']]);$this->assertTrue($role->hasPermissionTo('classrooms.view'));$own=$service->create($actor,['display_name'=>'Uji Sendiri','permissions'=>['classrooms.view-own']]);$this->assertFalse($own->hasPermissionTo('classrooms.view'));}}
